from __future__ import annotations

import base64

from PySide6.QtGui import QPixmap


_SAKURA_PNG_B64 = (
    ""
)


def load_sakura_sprite() -> QPixmap:
    pixmap = QPixmap()
    if not pixmap.loadFromData(base64.b64decode(_SAKURA_PNG_B64), "PNG"):
        raise RuntimeError("Failed to load embedded sakura sprite")
    return pixmap
